/**
 * Asserts that the resolved Vite version is 8 or later.
 * Throws a descriptive error if an older version is found, which can happen when the
 * project's node_modules contains a Vite version that overrides dt-app's bundled Vite.
 * Call this before any --optimize code path that relies on rolldownOptions (Vite 8-only API).
 *
 * @throws {Error} If the resolved Vite major version is less than 8.
 * @returns A promise that resolves when the version check passes.
 */
export declare function assertVite8(): Promise<void>;
